#include "netlib.h"
static u16 be16(const u8 *p){return (u16)((u16)p[0]<<8|p[1]);}
static int wait_recv(int fd,void *out,u32 cap){int r;u32 begin=Tick();while((r=recv(fd,out,cap))==S_AGAIN&&Tick()-begin<300)Yield(1);return r;}
static int skip_name(const u8 *bytes,u32 size,u32 *pos){u32 n=0;while(*pos<size&&n++<128){u8 c=bytes[(*pos)++];if(!c)return 0;if((c&0xc0)==0xc0){if(*pos>=size)return S_INVALID;u32 target=((u32)(c&63)<<8)|bytes[(*pos)++];return target<size?0:S_INVALID;}if(c>63||c>size-*pos)return S_INVALID;*pos+=c;}return S_INVALID;}
int DnsResolve(const char *host,u32 *address){u8 query[256],reply[512];memset(query,0,sizeof(query));u16 id=(u16)(Tick()^0x534e);query[0]=(u8)(id>>8);query[1]=(u8)id;query[2]=1;query[5]=1;u32 pos=12,start=0,len=strlen(host);if(!len||len>127)return S_INVALID;
 while(start<len){u32 end=start;while(host[end]&&host[end]!='.')end++;u32 n=end-start;if(!n||n>63||pos+n+6>sizeof(query))return S_INVALID;query[pos++]=(u8)n;memcpy(query+pos,host+start,n);pos+=n;start=end+(host[end]=='.');}query[pos++]=0;query[pos++]=0;query[pos++]=1;query[pos++]=0;query[pos++]=1;int fd=socket(NET_UDP);if(fd<0)return fd;int r=connect(fd,53);if(r<0){Close(fd);return r;}r=send(fd,query,pos);if(r<0){Close(fd);return r;}r=wait_recv(fd,reply,sizeof(reply));Close(fd);if(r<12||be16(reply)!=id||(reply[2]&0x82)!=0x80||(reply[3]&15)||be16(reply+4)!=1||!be16(reply+6))return S_IO;u32 size=(u32)r;pos=12;if(skip_name(reply,size,&pos)<0||pos+4>size||be16(reply+pos)!=1||be16(reply+pos+2)!=1)return S_INVALID;pos+=4;
 for(u32 i=0;i<be16(reply+6)&&i<16;i++){if(skip_name(reply,size,&pos)<0||pos+10>size)return S_INVALID;u16 type=be16(reply+pos),cls=be16(reply+pos+2),bytes=be16(reply+pos+8);pos+=10;if(bytes>size-pos)return S_INVALID;if(type==1&&cls==1&&bytes==4){*address=((u32)be16(reply+pos)<<16)|be16(reply+pos+2);return 0;}pos+=bytes;}return S_NOTFOUND;}
int HttpGet(u16 port,const char *path,char *out,u32 cap){if(!cap||cap>65536||!path[0]||strlen(path)>120)return S_INVALID;for(u32 i=0;path[i];i++)if((u8)path[i]<=32||(u8)path[i]==127)return S_INVALID;if(path[0]!='/')return S_INVALID;char request[180];copy(request,"GET ");copy(request+4,path);copy(request+strlen(request)," HTTP/1.0\r\nHost: localhost\r\nConnection: close\r\n\r\n");int fd=socket(NET_TCP);if(fd<0)return fd;int r;u32 begin=Tick();while((r=connect(fd,port))==S_AGAIN&&Tick()-begin<300)Yield(1);if(r<0){Close(fd);return r;}r=send(fd,request,strlen(request));if(r<0){Close(fd);return r;}u32 used=0;while(used+1<cap){r=wait_recv(fd,out+used,cap-used-1);if(r==0)break;if(r<0){Close(fd);return r;}used+=(u32)r;}Close(fd);out[used]=0;return (int)used;}
